-- ============================================================
-- IMPORT CATALOGO PIATTI da "File Excel/ElencoPiatti.xls"
-- Generato il 2026-08-29 · 4837 piatti
--
-- Cosa fa: allinea public.piatti al foglio "Elenco" del file della cucina.
-- È un UPSERT CONSERVATIVO: inserisce i piatti mancanti e completa quelli
-- già presenti, ma non cancella mai un dato che in Excel non c'è e non
-- sovrascrive le classificazioni fatte a mano dall'utente.
--
-- Contenuto:
--   · 4837 piatti  (portata: 343 antipasti, 1912 primi, 2169 secondi, 413 contorni)
--   · categoria assegnata a 4807/4837 (99.4%):
--     1482 carne · 1045 pesce · 2280 vegetariano · 30 da classificare a mano
--   · 797 piatti con allergeni UE, letti dalle annotazioni "(All. 1,7,8)"
--     lasciate dalla cucina in fondo alla ricetta
--
-- ⚠️ 135 dessert e 13 righe non-piatto (testi del footer, "CENA", una salsa)
--    sono ESCLUSI: vedi la nota in fondo al file.
--
-- Come si applica: Supabase → SQL Editor → incolla ed esegui.
-- Tutto in una transazione: se qualcosa fallisce non resta nulla a metà.
-- Rieseguirlo è innocuo (idempotente).
-- ============================================================

begin;

-- ── Preflight: il vocabolario dei tipi deve esistere (FK di piatti.tipo) ──
on conflict (code) do nothing;

-- ── Preflight: nomi lunghi ────────────────────────────────────────────
-- 651 piatti hanno nome_it di 55+ caratteri. Lo schema originale aveva
-- un CHECK char_length(nome_it) < 55 che li rifiuterebbe; sul DB di Hotel
-- Garden non c'è (l'import del 2026 li aveva già caricati), ma su un cliente
-- nuovo sì. Qui lo rileviamo e ci fermiamo con un messaggio chiaro invece di
-- far esplodere l'insert a metà.
do $$
declare v_check text;
begin
  select conname into v_check from pg_constraint
   where conrelid = 'public.piatti'::regclass and contype = 'c'
     and pg_get_constraintdef(oid) ilike '%char_length(nome_it)%';
  if v_check is not null then
    raise exception using message =
      'Il vincolo ' || v_check || ' limita nome_it a 55 caratteri, ma 651 piatti '
      'del file della cucina lo superano. Rimuovilo prima di importare: '
      'alter table public.piatti drop constraint ' || v_check || ';';
  end if;
end $$;

-- ── Staging ──────────────────────────────────────────────────────────
-- Colonne tutte NULLABLE, al contrario di public.piatti: in Excel "non
-- compilato" e "no" sono cose diverse, e solo tenendole distinte il merge
-- qui sotto può evitare di trasformare un campo ignoto in un `false`.
create temp table _piatti_xls (
  id bigint primary key,
  nome_it text, nome_en text, nome_fr text, nome_de text,
  tipo text, categoria text,
  vegetariano boolean, vegano boolean, no_lattosio boolean, locale boolean,
  ricetta text,
  ha_allergeni boolean,
  all_glutine boolean, all_crostacei boolean, all_uova boolean, all_pesce boolean, all_arachidi boolean, all_soia boolean, all_latte boolean, all_frutta_guscio boolean, all_sedano boolean, all_senape boolean, all_sesamo boolean, all_solfiti boolean, all_lupini boolean, all_molluschi boolean
) on commit drop;

-- righe 1–400

-- righe 401–800

-- righe 801–1200

-- righe 1201–1600

-- righe 1601–2000

-- righe 2001–2400

-- righe 2401–2800

-- righe 2801–3200

-- righe 3201–3600

-- righe 3601–4000

-- righe 4001–4400

-- righe 4401–4800

-- righe 4801–4837

-- ── 1. I piatti che ancora non ci sono ───────────────────────────────
-- Solo inserimento: le righe già a DB non vengono toccate qui, le aggiorna
-- lo statement 2, che può ragionare sui NULL della staging.
  id, nome_it, nome_en, nome_fr, nome_de, tipo, categoria,
  vegetariano, vegano, no_lattosio, locale, ricetta, all_glutine, all_crostacei, all_uova, all_pesce, all_arachidi, all_soia, all_latte, all_frutta_guscio, all_sedano, all_senape, all_sesamo, all_solfiti, all_lupini, all_molluschi
)
select
  x.id, x.nome_it, x.nome_en, x.nome_fr, x.nome_de, x.tipo, x.categoria,
  coalesce(x.vegetariano,false), coalesce(x.vegano,false),
  coalesce(x.no_lattosio,false), coalesce(x.locale,false), x.ricetta,
  coalesce(x.all_glutine,false), coalesce(x.all_crostacei,false), coalesce(x.all_uova,false), coalesce(x.all_pesce,false), coalesce(x.all_arachidi,false), coalesce(x.all_soia,false), coalesce(x.all_latte,false), coalesce(x.all_frutta_guscio,false), coalesce(x.all_sedano,false), coalesce(x.all_senape,false), coalesce(x.all_sesamo,false), coalesce(x.all_solfiti,false), coalesce(x.all_lupini,false), coalesce(x.all_molluschi,false)
from _piatti_xls x
on conflict (id) do nothing;

-- ── 2. I piatti già presenti ─────────────────────────────────────────
-- Merge conservativo. La regola generale: il file della cucina vince dove
-- dice qualcosa, il DB vince dove il file tace. In Excel "casella vuota" e
-- "no" sono due cose diverse (2.782 righe hanno le caratteristiche non
-- compilate) ed è per questo che la staging ha le colonne nullable: un
-- campo non compilato non deve diventare un `false`.
update public.piatti p set
  -- Nomi, portata, ricetta: il file è la fonte di verità, ma una cella
  -- vuota non cancella quello che a DB c'è già.
  nome_it     = x.nome_it,
  nome_en     = coalesce(x.nome_en, p.nome_en),
  nome_fr     = coalesce(x.nome_fr, p.nome_fr),
  nome_de     = coalesce(x.nome_de, p.nome_de),
  tipo        = x.tipo,
  ricetta     = coalesce(x.ricetta, p.ricetta),

  -- Categoria: si scrive SOLO dove manca. Se qualcuno l'ha già scelta dal
  -- form vince la sua, non la deduzione automatica di questo import.
  categoria   = coalesce(p.categoria, x.categoria),

  -- Caratteristiche: il file le corregge quando le dichiara (anche da "si"
  -- a "no"), ma dove la casella è vuota resta il valore a DB.
  vegetariano = coalesce(x.vegetariano, p.vegetariano),
  vegano      = coalesce(x.vegano,      p.vegano),
  no_lattosio = coalesce(x.no_lattosio, p.no_lattosio),
  locale      = coalesce(x.locale,      p.locale),

  -- Allergeni: solo aggiunti, mai tolti. Sono 797 i piatti in cui la
  -- cucina li ha annotati in ricetta; per tutti gli altri x.all_* è false e
  -- l'OR lascia il piatto com'era. Non annotare non è dichiarare l'assenza,
  -- e un allergene inserito a mano nell'app non va perso.
  all_glutine       = p.all_glutine or coalesce(x.all_glutine, false),
  all_crostacei     = p.all_crostacei or coalesce(x.all_crostacei, false),
  all_uova          = p.all_uova or coalesce(x.all_uova, false),
  all_pesce         = p.all_pesce or coalesce(x.all_pesce, false),
  all_arachidi      = p.all_arachidi or coalesce(x.all_arachidi, false),
  all_soia          = p.all_soia or coalesce(x.all_soia, false),
  all_latte         = p.all_latte or coalesce(x.all_latte, false),
  all_frutta_guscio = p.all_frutta_guscio or coalesce(x.all_frutta_guscio, false),
  all_sedano        = p.all_sedano or coalesce(x.all_sedano, false),
  all_senape        = p.all_senape or coalesce(x.all_senape, false),
  all_sesamo        = p.all_sesamo or coalesce(x.all_sesamo, false),
  all_solfiti       = p.all_solfiti or coalesce(x.all_solfiti, false),
  all_lupini        = p.all_lupini or coalesce(x.all_lupini, false),
  all_molluschi     = p.all_molluschi or coalesce(x.all_molluschi, false)
from _piatti_xls x
where x.id = p.id;

commit;

-- ── Verifica ─────────────────────────────────────────────────────────
-- Attesa: almeno 4837 piatti presenti, categoria su ~99%.
select
  (select count(*) from public.piatti)                              as piatti_totali,
  (select count(*) from public.piatti where categoria is not null)  as con_categoria,
  (select count(*) from public.piatti where ricetta is not null)    as con_ricetta,
  (select count(*) from public.piatti
    where all_glutine or all_crostacei or all_uova or all_pesce or all_arachidi
       or all_soia or all_latte or all_frutta_guscio or all_sedano or all_senape
       or all_sesamo or all_solfiti or all_lupini or all_molluschi)  as con_allergeni;

select tipo, categoria, count(*) from public.piatti group by 1,2 order by 1,2;

-- I 30 piatti che l'import lascia senza categoria: nomi di fantasia dello
-- chef ("alla Mamma Rosa", "Moda dello Chef") o piatti misti carne+pesce.
-- Non si indovinano: li classifica l'utente dal form, come per i 13 della
-- migrazione 022.
select id, nome_it from public.piatti where categoria is null order by id;

-- ── Righe del file NON importate ─────────────────────────────────────
-- 135 dessert (tipo 'des'): il dessert non esiste come piatto, a fine pasto
--   c'è sempre e solo il "Buffet di dessert", che è un flag del menù
--   (menu_flags.show_buffet_dessert). Deciso dalla migrazione 019.
-- 7 dessert sfuggiti al tipo 'des' (mousse al limone, crème caramel,
--   quadrotti di cacao, crema chantilly, crema di arance, dessert al
--   carrello, e la riga "Buffet di dessert" stessa).
-- 6 righe che non sono piatti: "CENA", "Antipasti misti vedi ultime righe",
--   "A richiesta singola ricetta con relativi allergeni", due testi del
--   footer con i prezzi à la carte, e "Salsa Bernese".
-- 1 riga senza nome italiano e 1 segnaposto ("*********").
